import time

class RateLimiter:
    """
    Implements a sliding window rate limiter using a timestamp dictionary to count requests.
    """

    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.request_count = {}

    def allow(self) -> bool:
        current_time = time.time()
        window_start = current_time - self.window_seconds

        # Remove timestamps from the count that are outside the window
        self.request_count = {key: value for key, value in self.request_count.items() if key > window_start}

        # Check if we can allow a new request
        if len(self.request_count) < self.max_requests:
            self.request_count[current_time] = self.request_count.get(current_time, 0) + 1
            return True

        return False
